custom_css:
/* ============================================================
 * Nord-Sharp 初版
 * 气质：北极冷色 + 微圆角3px(sharp系,非Poimandres药丸) + 纯色平面 + frost 极克制。
 * 现代卡片化：发丝细边 hairline + 软弥散阴影 + 扁平输入 + 微错位(AI微左/用户微右)。
 * 不抄 Gruvbox 骨架：无厚圆角、无左竖线、无颗粒底、frost 仅关键强调。
 * ============================================================ */

@import url('https://cdn.jsdelivr.net/npm/@lobehub/webfont-harmony-sans-sc@1.0.0/css/index-full.css');
@import url('https://cdn.jsdelivr.net/npm/@fontsource/jetbrains-mono@5.0.0/index.css');

:root {
  /* --- Nord 原子色（固定，变体不动这层）--- */
  --nord0:  #2e3440;   /* polar night 最暗 = 底 */
  --nord1:  #3b4252;   /* surface = 卡片 */
  --nord2:  #434c5e;   /* 卡片浮起 / hover */
  --nord3:  #4c566a;   /* 备用边 */
  --nord4:  #d8dee9;   /* snow 主字 */
  --nord5:  #e5e9f0;
  --nord6:  #eceff4;
  --nord7:  #8fbcbb;   /* frost teal */
  --nord8:  #88c0d0;   /* frost cyan ★ 主强调 */
  --nord9:  #81a1c1;   /* frost blue */
  --nord10: #5e81ac;   /* frost deep */
  --nord11: #bf616a;   /* aurora red / danger */
  --nord12: #d08770;   /* aurora orange */
  --nord13: #ebcb8b;   /* aurora yellow / warn */
  --nord14: #a3be8c;   /* aurora green / success */
  --nord15: #b48ead;   /* aurora purple */

  /* --- 语义层（变体只改这层）--- */
  --bg:         var(--nord0);
  --card:       var(--nord1);
  --card-hi:    var(--nord2);
  --border:     rgba(216,222,233,0.10);   /* 发丝细边 hairline，现代卡片非重边 */
  --text:       var(--nord4);
  --text-dim:   #aeb4c4;
  --text-faint: var(--nord3);
  --accent:     var(--nord8);
  --danger:     var(--nord11);
  --warn:       var(--nord13);
  --success:    var(--nord14);
  --info:       var(--nord9);
  --on-accent:  var(--nord0);

  --r: 3px;  /* 微圆角：纯0配重投影=brutalist复古，3px=现代卡片仍sharp系 */

  /* 卡片 elevation：软弥散阴影(现代) + 极淡顶边光 */
  --shadow-card: 0 1px 3px rgba(0,0,0,0.25), 0 8px 20px rgba(0,0,0,0.18);
  --edge-light:  inset 0 1px 0 rgba(216,222,233,0.05);

  --font-sans: 'HarmonyOS Sans SC','HarmonyOS_Sans_SC',system-ui,-apple-system,'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif;
  --font-mono: 'JetBrains Mono','Cascadia Code',ui-monospace,Menlo,Consolas,monospace;
}

/* ---全局微圆角 + 底 + 字--- */
* { border-radius: var(--r) !important; }
body { background-color: var(--bg) !important; color: var(--text) !important; font-family: var(--font-sans) !important; }
input, textarea, select, option, button, .text_pole, #send_textarea { font-family: var(--font-sans) !important; }
.mes_text, .mes_text p, .ch_name, .mesIDDisplay, .mes_timer, .tokenCounterDisplay { font-family: var(--font-sans) !important; color: var(--text) !important; }
.ch_name { color: var(--text) !important; font-weight: 700 !important; letter-spacing: .02em !important; }
code, pre, .hljs, .katex { font-family: var(--font-mono) !important; }

/* ---聊天消息 = 现代卡片 + 微错位（AI 微靠左 / 用户 微靠右）--- */
.mes {
  background-color: var(--card) !important;
  border: 1px solid var(--border) !important;
  box-shadow: var(--shadow-card), var(--edge-light) !important;
  padding: 14px 16px !important;
  margin-bottom: 14px !important;
  margin-left: 0 !important;
  margin-right: 10px !important;
}
.mes[is_user="true"] {
  margin-left: 10px !important;
  margin-right: 0 !important;
}

/* ---面板/抽屉/popup = 卡片浮起--- */
#right-nav-panel, #left-nav-panel,
#character_popup, #dialogue_popup, .popup, .draggable,
#WorldInfo, #floatingPrompt {
  background-color: var(--card) !important;
  border: 1px solid var(--border) !important;
  box-shadow: var(--shadow-card), var(--edge-light) !important;
}
#right-nav-panel .drawer-content, #left-nav-panel .drawer-content {
  background-color: transparent !important; border-color: transparent !important; box-shadow: none !important;
}

/* ---标题/区块头 = 小卡片--- */
.inline-drawer-header, .standoutHeader,
.drawer-content h3, .drawer-content h4:not(.margin0),
#character_popup h3, .popup h3 {
  background-color: var(--card-hi) !important;
  border: 1px solid var(--border) !important;
  box-shadow: var(--edge-light) !important;
  color: var(--text) !important;
}

/* ---输入栏 = 卡片；输入框 = 扁平 hairline（现代，非 etched 凹陷）--- */
#send_form {
  background-color: var(--card) !important;
  border: 1px solid var(--border) !important;
  box-shadow: var(--shadow-card), var(--edge-light) !important;
}
.text_pole, textarea, #send_textarea, select,
input[type="text"], input[type="password"], input[type="number"] {
  background-color: var(--bg) !important;
  color: var(--text) !important;
  border: 1px solid var(--border) !important;
}

/* ---按钮 = 微浮，hover frost--- */
.menu_button, .right_menu_button, input[type="button"], input[type="submit"] {
  background-color: var(--card-hi) !important;
  color: var(--text) !important;
  border: 1px solid var(--border) !important;
  box-shadow: var(--edge-light) !important;
}
.menu_button:hover, .right_menu_button:hover, input[type="button"]:hover, input[type="submit"]:hover {
  background-color: var(--accent) !important; color: var(--on-accent) !important; border-color: var(--accent) !important;
}
.menu_button:active, input[type="button"]:active, input[type="submit"]:active {
  background-color: var(--nord9) !important; color: var(--on-accent) !important;
}

/* ---发送/继续 = frost 实底--- */
#send_but, #mes_continue {
  background-color: var(--accent) !important;
  color: var(--on-accent) !important;
  border: 1px solid var(--accent) !important;
  box-shadow: var(--shadow-card) !important;
}
#send_but:hover, #mes_continue:hover { background-color: var(--nord7) !important; border-color: var(--nord7) !important; }

/* ---聊天容器：纯底，卡片浮其上--- */
#chat { background-color: var(--bg) !important; border: none !important; box-shadow: none !important; }

/* ---链接/选中：frost--- */
a { color: var(--accent) !important; }
::selection { background: rgba(136,192,208,0.30) !important; color: var(--text) !important; }

/* ---代码块：扁平 hairline + Nord 语法色--- */
pre, code, .hljs, code.hljs {
  background-color: var(--bg) !important;
  border: 1px solid var(--border) !important;
}
.hljs-keyword, .hljs-built_in, .hljs-type { color: var(--nord9) !important; }
.hljs-string, .hljs-attr, .hljs-symbol { color: var(--nord14) !important; }
.hljs-number, .hljs-literal { color: var(--nord13) !important; }
.hljs-comment { color: var(--nord3) !important; font-style: italic !important; }
.hljs-function .hljs-title, .hljs-title { color: var(--nord8) !important; }
.hljs-variable, .hljs-params { color: var(--text) !important; }
.hljs-tag, .hljs-name { color: var(--nord9) !important; }
.hljs-regexp { color: var(--nord12) !important; }

/* ---滚动条：细冷--- */
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: var(--bg); }
::-webkit-scrollbar-thumb { background: var(--nord3); border: 2px solid var(--bg); }
::-webkit-scrollbar-thumb:hover { background: var(--nord9); }
